<?php

namespace App\Http\Controllers\Api;

use App\Http\Controllers\Controller;
use App\Models\ListingDocument;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;

/**
 * "Manage Documents": every document the user can access across listings
 * (original Reozom DocumentsController@manageDocument). Actions on a single document
 * (view, download, rename, delete, email, sign) use the existing per-listing endpoints.
 */
class ManageDocumentsController extends Controller
{
    /** Document types generated by the system before document templates existed. */
    private const LEGACY_GENERATED_TYPES = [
        'sellers_disclosure', 'lead_disclosure', 'condo_disclosure', 'listing_agreement', 'agency_disclosure',
    ];

    public function index(Request $request): JsonResponse
    {
        $user = $request->user();

        $validated = $request->validate([
            'search' => 'nullable|string|max:100',
            'state' => 'nullable|string|max:10',
            'status' => 'nullable|string|in:signed,unsigned,uploaded,approved,rejected,pending_review',
            'kind' => 'nullable|string|in:generated,uploaded',
            'listing_id' => 'nullable|integer',
            'per_page' => 'nullable|integer|min:5|max:100',
        ]);

        $query = ListingDocument::query()
            ->with(['listing:id,reference_code,address,city,state,zip,user_id,service_package_id,listing_process_id', 'listing.user:id,name', 'template:id,name,source'])
            ->latest('updated_at');

        // Who sees what: admin all; agent the listings under their packages or processes; seller their own
        if ($user->isAdmin()) {
            // no restriction
        } elseif ($user->isAgent()) {
            $query->whereHas('listing', fn (Builder $q) => $q
                ->whereHas('servicePackage', fn (Builder $p) => $p->where('agent_id', $user->id))
                ->orWhereHas('listingProcess', fn (Builder $p) => $p->where('agent_id', $user->id)));
        } else {
            $query->whereHas('listing', fn (Builder $q) => $q->where('user_id', $user->id));
        }

        if (! empty($validated['search'])) {
            $term = '%'.$validated['search'].'%';
            $query->where(fn (Builder $q) => $q
                ->where('original_name', 'like', $term)
                ->orWhereHas('listing', fn (Builder $l) => $l
                    ->where('address', 'like', $term)
                    ->orWhere('city', 'like', $term)
                    ->orWhere('reference_code', 'like', $term)));
        }

        if (! empty($validated['state'])) {
            $query->whereHas('listing', fn (Builder $l) => $l->where('state', strtoupper($validated['state'])));
        }

        if (! empty($validated['status'])) {
            $query->where('status', $validated['status']);
        }

        if (! empty($validated['listing_id'])) {
            $query->where('listing_id', $validated['listing_id']);
        }

        if (($validated['kind'] ?? null) === 'generated') {
            $query->where(fn (Builder $q) => $q->whereNotNull('document_template_id')->orWhereIn('type', self::LEGACY_GENERATED_TYPES));
        } elseif (($validated['kind'] ?? null) === 'uploaded') {
            $query->whereNull('document_template_id')->whereNotIn('type', self::LEGACY_GENERATED_TYPES);
        }

        $page = $query->paginate($validated['per_page'] ?? 20);

        $items = collect($page->items())->map(function (ListingDocument $doc) use ($user) {
            $isGenerated = $doc->document_template_id !== null || in_array($doc->type, self::LEGACY_GENERATED_TYPES, true);
            $listing = $doc->listing;

            return [
                'id' => $doc->id,
                'listingId' => $doc->listing_id,
                'listingReference' => $listing?->reference_code,
                'listingAddress' => trim(implode(', ', array_filter([$listing?->address, $listing?->city, $listing?->state]))),
                'state' => $listing?->state,
                'sellerName' => $listing?->user?->name,
                'name' => str_replace('.pdf', '', $doc->original_name),
                'fileName' => $doc->original_name,
                'type' => $doc->type,
                'kind' => $isGenerated ? 'generated' : 'uploaded',
                'status' => $doc->status,
                'signedAt' => $doc->signed_at?->toIso8601String(),
                'size' => $doc->size,
                'updatedAt' => $doc->updated_at?->toIso8601String(),
                // Generated documents are managed by the system and can't be deleted or renamed here
                'canManage' => ! $isGenerated && $listing !== null && $user->can('update', $listing),
            ];
        });

        return api_success([
            'items' => $items,
            'meta' => [
                'currentPage' => $page->currentPage(),
                'lastPage' => $page->lastPage(),
                'perPage' => $page->perPage(),
                'total' => $page->total(),
            ],
        ]);
    }
}
